'use strict';

// MODULES //

var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var truncf = require( '@stdlib/math/base/special/truncf' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var expmultif = require( './expmultif.js' );


// VARIABLES //

var LN2_HI = f32( 6.9314575195e-01 );     // 0x3F317200
var LN2_LO = f32( 1.4286067653e-06 );     // 0x35BFBE8E
var INVLN2 = f32( 1.4426950216e+00 );     // 0x3FB8AA3B
var OVERFLOW = f32( 8.8722831726e+01 );   // 0x42B17217
var UNDERFLOW = f32( -1.0397208405e+02 ); // 0xC2CFF1B5
var NEARZERO = f32( 1.0 / (1 << 13) );    // 0x39000000
var NEG_NEARZERO = f32( -NEARZERO );      // 0xB9000000
var HALF = f32( 0.5 );
var ONE = f32( 1.0 );


// MAIN //

/**
* Evaluates the natural exponential function for a single-precision floating-point number.
*
* ## Method
*
* 1.  We reduce \\( x \\) to an \\( r \\) so that \\( |r| \leq 0.5 \cdot \ln(2) \approx 0.34658 \\). Given \\( x \\), we find an \\( r \\) and integer \\( k \\) such that
*
*     ```tex
*     \begin{align*}
*     x &= k \cdot \ln(2) + r \\
*     |r| &\leq 0.5 \cdot \ln(2)
*     \end{align*}
*     ```
*
*     <!-- <note> -->
*
*     \\( r \\) can be represented as \\( r = \mathrm{hi} - \mathrm{lo} \\) for better accuracy.
*
*     <!-- </note> -->
*
* 2.  We approximate of \\( e^{r} \\) by a special rational function on the interval \\(\[0,0.34658]\\):
*
*     ```tex
*     \begin{align*}
*     R\left(r^2\right) &= r \cdot \frac{ e^{r}+1 }{ e^{r}-1 } \\
*     &= 2 + \frac{r^2}{6} - \frac{r^4}{360} + \ldots
*     \end{align*}
*     ```
*
*     We use a special Remes algorithm on \\(\[0,0.34658]\\) to generate a polynomial of degree \\(2\\) to approximate \\(R\\). The maximum error of this polynomial approximation is bounded by \\(2^{-27.74}\\). In other words,
*
*     ```tex
*     R(z) \sim 2 + P_1 z + P_2 z^2
*     ```
*
*     where \\( z = r^2 \\) and
*
*     ```tex
*     \left|  2 + P_1 z + P_2 z^2  - R(z) \right| \leq 2^{-27.74}
*     ```
*
*     <!-- <note> -->
*
*     The values of \\( P_1 \\) to \\( P_2 \\) are listed in the source code.
*
*     <!-- </note> -->
*
*     The computation of \\( e^{r} \\) thus becomes
*
*     ```tex
*     \begin{align*}
*     e^{r} &= 1 + \frac{2r}{R-r} \\
*           &= 1 + r + \frac{r \cdot R_1(r)}{2 - R_1(r)}\ \text{for better accuracy}
*     \end{align*}
*     ```
*
*     where
*
*     ```tex
*     R_1(r) = r - P_1\ r^2 + P_2\ r^4
*     ```
*
* 3.  We scale back to obtain \\( e^{x} \\). From step 1, we have
*
*     ```tex
*     e^{x} = 2^k e^{r}
*     ```
*
* ## Special Cases
*
* ```tex
* \begin{align*}
* e^\infty &= \infty \\
* e^{-\infty} &= 0 \\
* e^{\mathrm{NaN}} &= \mathrm{NaN} \\
* e^0 &= 1\ \mathrm{is\ exact\ for\ finite\ argument\ only}
* \end{align*}
* ```
*
* ## Notes
*
* -   The hexadecimal values included in the source code are the intended ones for the used constants. Decimal values may be used, provided that the compiler will convert from decimal to binary accurately enough to produce the intended hexadecimal values.
*
* @param {number} x - input value
* @returns {number} function value
*
* @example
* var v = expf( 4.0 );
* // returns ~54.5982
*
* @example
* var v = expf( -9.0 );
* // returns ~1.234e-4
*
* @example
* var v = expf( 0.0 );
* // returns 1.0
*
* @example
* var v = expf( NaN );
* // returns NaN
*/
function expf( x ) {
	var hi;
	var lo;
	var k;

	x = f32( x );
	if ( isnanf( x ) || x === PINF ) {
		return x;
	}
	if ( x === NINF ) {
		return 0.0;
	}
	if ( x > OVERFLOW ) {
		return PINF;
	}
	if ( x < UNDERFLOW ) {
		return 0.0;
	}
	if (
		x > NEG_NEARZERO &&
		x < NEARZERO
	) {
		return f32( ONE + x );
	}
	// Reduce and compute `r = hi - lo` for extra precision...
	if ( x < 0.0 ) {
		k = truncf( f32( f32( INVLN2*x ) - HALF ) );
	} else {
		k = truncf( f32( f32( INVLN2*x ) + HALF ) );
	}
	hi = f32( x - f32( k*LN2_HI ) );
	lo = f32( k * LN2_LO );

	return expmultif( hi, lo, k );
}


// EXPORTS //

module.exports = expf;
